final_sql:
SELECT CountryId, CountryName FROM countries WHERE CountryId IN (
    SELECT DISTINCT Country FROM car_makers WHERE Id IN (
        SELECT Maker FROM model_list WHERE Model IN (
            SELECT Model FROM car_names WHERE Make LIKE '%fiat%'
        )
    )
) OR CountryId IN (
    SELECT DISTINCT Country FROM car_makers GROUP BY Country HAVING COUNT(*) > 3
)

